/**
 * @file createAbortable - Make promise cancellable with AbortController
 * @module @dsai-io/react/utils/async
 *
 * Enterprise-grade abortable promise wrapper with:
 * - AbortController integration
 * - Automatic cleanup
 * - Type-safe cancellation
 * - React-friendly API
 */

/**
 * Result of createAbortable
 */
export interface AbortablePromise<T> {
  /** The wrapped promise */
  promise: Promise<T>;
  /** Function to abort the operation */
  abort: () => void;
  /** The underlying AbortController */
  controller: AbortController;
  /** Whether the operation has been aborted */
  readonly aborted: boolean;
}

/**
 * Create a cancellable promise wrapper
 *
 * Wraps an async operation to make it cancellable via AbortController.
 * When aborted, the promise rejects with an AbortError.
 *
 * @param fn - Async function that receives an AbortSignal
 * @returns Object with promise, abort function, and controller
 *
 * @example
 * ```tsx
 * // Basic usage
 * const { promise, abort } = createAbortable(async (signal) => {
 *   const response = await fetch('/api/data', { signal });
 *   return response.json();
 * });
 *
 * // Abort after 5 seconds
 * setTimeout(abort, 5000);
 *
 * try {
 *   const data = await promise;
 *   console.log('Data:', data);
 * } catch (error) {
 *   if (error.name === 'AbortError') {
 *     console.log('Request was cancelled');
 *   }
 * }
 *
 * // In React useEffect
 * useEffect(() => {
 *   const { promise, abort } = createAbortable(async (signal) => {
 *     const data = await fetchData({ signal });
 *     setData(data);
 *   });
 *
 *   promise.catch(error => {
 *     if (error.name !== 'AbortError') {
 *       setError(error);
 *     }
 *   });
 *
 *   return abort; // Cleanup on unmount
 * }, []);
 *
 * // With multiple fetch calls
 * const { promise, abort } = createAbortable(async (signal) => {
 *   const [users, posts] = await Promise.all([
 *     fetch('/api/users', { signal }).then(r => r.json()),
 *     fetch('/api/posts', { signal }).then(r => r.json())
 *   ]);
 *   return { users, posts };
 * });
 *
 * // Custom abort reason
 * const { promise, controller } = createAbortable(async (signal) => {
 *   // Long running operation
 * });
 *
 * controller.abort('User cancelled');
 * ```
 */
export function createAbortable<T>(fn: (signal: AbortSignal) => Promise<T>): AbortablePromise<T> {
  const controller = new AbortController();

  const promise = new Promise<T>((resolve, reject) => {
    // Check if already aborted
    if (controller.signal.aborted) {
      reject(new DOMException('Aborted', 'AbortError'));
      return;
    }

    // Listen for abort
    const abortHandler = (): void => {
      reject(new DOMException('Aborted', 'AbortError'));
    };

    controller.signal.addEventListener('abort', abortHandler, { once: true });

    // Execute the function
    fn(controller.signal)
      .then((result) => {
        controller.signal.removeEventListener('abort', abortHandler);
        resolve(result);
      })
      .catch((error) => {
        controller.signal.removeEventListener('abort', abortHandler);
        reject(error);
      });
  });

  return {
    promise,
    abort: () => controller.abort(),
    controller,
    get aborted() {
      return controller.signal.aborted;
    },
  };
}

/**
 * @file createTaskQueue - Task queue for animations/transitions
 * @module @dsai-io/react/utils/async
 *
 * Enterprise-grade task queue with:
 * - Sequential or concurrent execution
 * - Priority support
 * - Pause/resume functionality
 * - Task cancellation
 * - Progress tracking
 */

/**
 * Task function type
 */
export type TaskFunction<T = void> = () => Promise<T> | T;

/**
 * Task item in the queue
 */
export interface QueuedTask<T = void> {
  /** Unique task ID */
  id: string;
  /** Task function to execute */
  fn: TaskFunction<T>;
  /** Task priority (higher = earlier execution) */
  priority: number;
  /** Promise that resolves when task completes */
  promise: Promise<T>;
  /** Resolve function for the task promise */
  resolve: (value: T) => void;
  /** Reject function for the task promise */
  reject: (error: unknown) => void;
}

/**
 * Options for task queue
 */
export interface TaskQueueOptions {
  /** Maximum concurrent tasks (default: 1 for sequential) */
  concurrency?: number;
  /** Whether to auto-start processing (default: true) */
  autoStart?: boolean;
}

/**
 * Task queue state
 */
export interface TaskQueueState {
  /** Number of pending tasks */
  pending: number;
  /** Number of currently running tasks */
  running: number;
  /** Whether the queue is paused */
  paused: boolean;
  /** Whether the queue is processing */
  processing: boolean;
}

/**
 * Task queue instance
 */
export interface TaskQueue {
  /** Add a task to the queue */
  enqueue: <T>(fn: TaskFunction<T>, priority?: number) => Promise<T>;
  /** Pause queue processing */
  pause: () => void;
  /** Resume queue processing */
  resume: () => void;
  /** Clear all pending tasks */
  clear: () => void;
  /** Get current queue state */
  getState: () => TaskQueueState;
  /** Wait for all tasks to complete */
  drain: () => Promise<void>;
}

let taskIdCounter = 0;

/**
 * Create a task queue for managing async operations
 *
 * Useful for coordinating animations, transitions, or any
 * operations that need to run in a controlled sequence.
 *
 * @param options - Queue configuration options
 * @returns Task queue instance
 *
 * @example
 * ```tsx
 * // Sequential queue (default)
 * const queue = createTaskQueue();
 *
 * queue.enqueue(async () => {
 *   await animateIn(element1);
 * });
 *
 * queue.enqueue(async () => {
 *   await animateIn(element2);
 * });
 *
 * // Elements animate one after another
 *
 * // Concurrent queue
 * const parallelQueue = createTaskQueue({ concurrency: 3 });
 *
 * // Up to 3 tasks run simultaneously
 * urls.forEach(url => {
 *   parallelQueue.enqueue(() => fetch(url));
 * });
 *
 * // With priority
 * const queue = createTaskQueue();
 *
 * queue.enqueue(() => lowPriorityTask(), 1);
 * queue.enqueue(() => highPriorityTask(), 10); // Runs first
 * queue.enqueue(() => mediumPriorityTask(), 5);
 *
 * // Pause/resume
 * const queue = createTaskQueue();
 *
 * queue.enqueue(() => task1());
 * queue.pause();
 * queue.enqueue(() => task2()); // Queued but not executed
 * queue.resume(); // task2 starts
 *
 * // Wait for completion
 * await queue.drain();
 * console.log('All tasks complete');
 *
 * // In React component
 * const queueRef = useRef(createTaskQueue());
 *
 * const handleClick = () => {
 *   queueRef.current.enqueue(async () => {
 *     await animateButton();
 *   });
 * };
 * ```
 */
export function createTaskQueue(options: TaskQueueOptions = {}): TaskQueue {
  const { concurrency = 1, autoStart = true } = options;

  const queue: QueuedTask<unknown>[] = [];
  let running = 0;
  let paused = !autoStart;
  let drainResolvers: (() => void)[] = [];

  const processNext = async (): Promise<void> => {
    if (paused || running >= concurrency || queue.length === 0) {
      // Check if we should resolve drain promises
      if (running === 0 && queue.length === 0) {
        drainResolvers.forEach((resolve) => {
          resolve();
        });
        drainResolvers = [];
      }
      return;
    }

    // Sort by priority (higher first) and get next task
    queue.sort((a, b) => b.priority - a.priority);
    const task = queue.shift();

    if (!task) {
      return;
    }

    running++;

    try {
      const result = await task.fn();
      task.resolve(result);
    } catch (error) {
      task.reject(error);
    } finally {
      running--;
      // Process next task
      processNext();
    }
  };

  return {
    enqueue<T>(fn: TaskFunction<T>, priority = 0): Promise<T> {
      let resolve!: (value: T) => void;
      let reject!: (error: unknown) => void;

      const promise = new Promise<T>((res, rej) => {
        resolve = res;
        reject = rej;
      });

      const task: QueuedTask<T> = {
        id: `task-${++taskIdCounter}`,
        fn,
        priority,
        promise,
        resolve,
        reject,
      };

      queue.push(task as QueuedTask<unknown>);

      // Start processing if not paused
      if (!paused) {
        processNext();
      }

      return promise;
    },

    pause(): void {
      paused = true;
    },

    resume(): void {
      paused = false;
      // Start processing any queued tasks
      for (let i = 0; i < concurrency; i++) {
        processNext();
      }
    },

    clear(): void {
      // Reject all pending tasks
      queue.forEach((task) => {
        task.reject(new Error('Task queue cleared'));
      });
      queue.length = 0;
    },

    getState(): TaskQueueState {
      return {
        pending: queue.length,
        running,
        paused,
        processing: running > 0,
      };
    },

    drain(): Promise<void> {
      if (running === 0 && queue.length === 0) {
        return Promise.resolve();
      }

      return new Promise((resolve) => {
        drainResolvers.push(resolve);
      });
    },
  };
}

/**
 * @file exponentialBackoff - Calculate exponential backoff delay with jitter
 * @module @dsai-io/react/utils/async
 *
 * Enterprise-grade backoff calculator with:
 * - Configurable base delay and multiplier
 * - Optional jitter to prevent thundering herd
 * - Maximum delay cap
 * - Attempt-based calculation
 */

/**
 * Generate a random fraction in [0, 1) using crypto when available.
 * Falls back to a time-based entropy source to avoid Math.random.
 */
function getSecureRandomFraction(): number {
  const cryptoObj = typeof globalThis.crypto !== 'undefined' ? globalThis.crypto : undefined;
  if (cryptoObj && typeof cryptoObj.getRandomValues === 'function') {
    const buffer = new Uint32Array(1);
    cryptoObj.getRandomValues(buffer);
    const value = buffer[0];
    return (value ?? 0) / 0xffffffff;
  }

  const timeSlice = Date.now() % 1000;
  return timeSlice / 1000;
}

/**
 * Options for exponential backoff calculation
 */
export interface ExponentialBackoffOptions {
  /** Base delay in milliseconds (default: 1000) */
  baseDelay?: number;
  /** Multiplier for each attempt (default: 2) */
  multiplier?: number;
  /** Maximum delay cap in milliseconds (default: 30000) */
  maxDelay?: number;
  /** Whether to add random jitter (default: true) */
  jitter?: boolean;
  /** Maximum jitter as percentage of delay (default: 0.25 = 25%) */
  jitterFactor?: number;
}

/**
 * Calculate exponential backoff delay for a given attempt
 *
 * Formula: min(maxDelay, baseDelay * (multiplier ^ attempt)) + jitter
 *
 * @param attempt - The current attempt number (0-indexed)
 * @param options - Backoff configuration options
 * @returns Delay in milliseconds before next retry
 *
 * @example
 * ```tsx
 * // Basic usage
 * exponentialBackoff(0); // ~1000ms (first retry)
 * exponentialBackoff(1); // ~2000ms (second retry)
 * exponentialBackoff(2); // ~4000ms (third retry)
 *
 * // Custom configuration
 * exponentialBackoff(2, {
 *   baseDelay: 500,
 *   multiplier: 3,
 *   maxDelay: 10000
 * }); // min(10000, 500 * 3^2) = 4500ms + jitter
 *
 * // Without jitter (deterministic)
 * exponentialBackoff(3, { jitter: false }); // Exactly 8000ms
 *
 * // Use in retry logic
 * async function fetchWithRetry(url: string, maxAttempts = 3) {
 *   for (let attempt = 0; attempt < maxAttempts; attempt++) {
 *     try {
 *       return await fetch(url);
 *     } catch (error) {
 *       if (attempt < maxAttempts - 1) {
 *         const delay = exponentialBackoff(attempt);
 *         await new Promise(resolve => setTimeout(resolve, delay));
 *       } else {
 *         throw error;
 *       }
 *     }
 *   }
 * }
 * ```
 */
export function exponentialBackoff(
  attempt: number,
  options: ExponentialBackoffOptions = {}
): number {
  const {
    baseDelay = 1000,
    multiplier = 2,
    maxDelay = 30000,
    jitter = true,
    jitterFactor = 0.25,
  } = options;

  // Validate inputs
  if (attempt < 0) {
    console.warn('[exponentialBackoff] Attempt must be >= 0, using 0');
    attempt = 0;
  }

  if (baseDelay <= 0) {
    console.warn('[exponentialBackoff] baseDelay must be > 0, using 1000');
    return 1000;
  }

  // Calculate base exponential delay
  const exponentialDelay = baseDelay * multiplier ** attempt;

  // Cap at maximum delay
  const cappedDelay = Math.min(maxDelay, exponentialDelay);

  // Add jitter if enabled
  if (jitter) {
    // Jitter range: delay * (1 - jitterFactor) to delay * (1 + jitterFactor)
    const jitterRange = cappedDelay * jitterFactor;
    const randomJitter = (getSecureRandomFraction() * 2 - 1) * jitterRange;
    return Math.max(0, Math.round(cappedDelay + randomJitter));
  }

  return Math.round(cappedDelay);
}

/**
 * @file Async & Control Flow utilities
 * @module @dsai-io/react/utils/async
 *
 * Enterprise-grade async utilities including:
 * - Retry with exponential backoff
 * - Promise timeout wrapper
 * - Abortable promises
 * - Task queuing and scheduling
 */

// Backoff utilities
export { exponentialBackoff } from './exponentialBackoff';
export type { ExponentialBackoffOptions } from './exponentialBackoff';

// Retry utilities
export { retryWithBackoff } from './retryWithBackoff';
export type { RetryResult, RetryWithBackoffOptions } from './retryWithBackoff';

// Timeout utilities
export { TimeoutError, withTimeout } from './withTimeout';
export type { WithTimeoutOptions } from './withTimeout';

// Abort utilities
export { createAbortable } from './createAbortable';
export type { AbortablePromise } from './createAbortable';

// Task queue utilities
export { createTaskQueue } from './createTaskQueue';
export type {
  QueuedTask,
  TaskFunction,
  TaskQueue,
  TaskQueueOptions,
  TaskQueueState,
} from './createTaskQueue';

// Task scheduling utilities
export { queueTask } from './queueTask';
export type { QueueTaskOptions, QueuedTaskHandle, TaskSchedule } from './queueTask';

/**
 * @file queueTask - Simple task scheduler using microtasks/macrotasks
 * @module @dsai-io/react/utils/async
 *
 * Enterprise-grade task scheduling with:
 * - Microtask (Promise-based) scheduling
 * - Macrotask (setTimeout-based) scheduling
 * - RequestAnimationFrame scheduling
 * - Idle callback scheduling
 */

/**
 * Task scheduling strategy
 */
export type TaskSchedule = 'microtask' | 'macrotask' | 'animationFrame' | 'idle';

/**
 * Options for queueTask
 */
export interface QueueTaskOptions {
  /** Scheduling strategy (default: 'microtask') */
  schedule?: TaskSchedule;
  /** Timeout for idle callback in ms (default: 1000) */
  idleTimeout?: number;
}

/**
 * Queued task handle for cancellation
 */
export interface QueuedTaskHandle {
  /** Cancel the queued task */
  cancel: () => void;
}

/**
 * Queue a task for later execution
 *
 * Provides different scheduling strategies for various use cases:
 * - microtask: Highest priority, runs after current script
 * - macrotask: Runs after microtasks and rendering
 * - animationFrame: Runs before next paint (for visual updates)
 * - idle: Runs when browser is idle (for non-critical work)
 *
 * @param fn - Function to execute
 * @param options - Scheduling options
 * @returns Handle with cancel method
 *
 * @example
 * ```tsx
 * // Microtask (default) - runs after current synchronous code
 * queueTask(() => {
 *   console.log('Runs in microtask');
 * });
 *
 * // Macrotask - runs after microtasks and rendering
 * queueTask(() => {
 *   console.log('Runs in macrotask');
 * }, { schedule: 'macrotask' });
 *
 * // Animation frame - for visual updates
 * queueTask(() => {
 *   element.style.transform = 'translateX(100px)';
 * }, { schedule: 'animationFrame' });
 *
 * // Idle callback - for non-critical work
 * queueTask(() => {
 *   performAnalytics();
 * }, { schedule: 'idle', idleTimeout: 2000 });
 *
 * // With cancellation
 * const handle = queueTask(() => {
 *   console.log('This might not run');
 * }, { schedule: 'macrotask' });
 *
 * handle.cancel(); // Cancels the task
 *
 * // In React component
 * useEffect(() => {
 *   const handle = queueTask(() => {
 *     // Update after paint
 *     measureElement();
 *   }, { schedule: 'animationFrame' });
 *
 *   return () => handle.cancel();
 * }, []);
 *
 * // Batch DOM updates
 * function batchUpdate(updates: (() => void)[]) {
 *   queueTask(() => {
 *     updates.forEach(update => update());
 *   }, { schedule: 'animationFrame' });
 * }
 * ```
 */
export function queueTask(fn: () => void, options: QueueTaskOptions = {}): QueuedTaskHandle {
  const { schedule = 'microtask', idleTimeout = 1000 } = options;

  let cancelled = false;
  let timeoutId: ReturnType<typeof setTimeout> | undefined;
  let rafId: number | undefined;
  let idleId: number | undefined;

  const wrappedFn = (): void => {
    if (!cancelled) {
      fn();
    }
  };

  switch (schedule) {
    case 'microtask':
      // Use queueMicrotask for highest priority async
      queueMicrotask(wrappedFn);
      break;

    case 'macrotask':
      // Use setTimeout(0) for macrotask
      timeoutId = setTimeout(wrappedFn, 0);
      break;

    case 'animationFrame':
      // Use requestAnimationFrame for visual updates
      if (typeof requestAnimationFrame !== 'undefined') {
        rafId = requestAnimationFrame(wrappedFn);
      } else {
        // Fallback for SSR
        timeoutId = setTimeout(wrappedFn, 16);
      }
      break;

    case 'idle':
      // Use requestIdleCallback for non-critical work
      if (typeof requestIdleCallback !== 'undefined') {
        idleId = requestIdleCallback(wrappedFn, { timeout: idleTimeout });
      } else {
        // Fallback for browsers without requestIdleCallback
        timeoutId = setTimeout(wrappedFn, 1);
      }
      break;

    default:
      console.warn(`[queueTask] Unknown schedule: ${schedule}, using microtask`);
      queueMicrotask(wrappedFn);
  }

  return {
    cancel(): void {
      cancelled = true;

      if (timeoutId !== undefined) {
        clearTimeout(timeoutId);
      }

      if (rafId !== undefined && typeof cancelAnimationFrame !== 'undefined') {
        cancelAnimationFrame(rafId);
      }

      if (idleId !== undefined && typeof cancelIdleCallback !== 'undefined') {
        cancelIdleCallback(idleId);
      }
    },
  };
}

/**
 * @file retryWithBackoff - Retry failed promises with exponential backoff
 * @module @dsai-io/react/utils/async
 *
 * Enterprise-grade retry utility with:
 * - Configurable max attempts
 * - Exponential backoff between retries
 * - Custom retry condition
 * - Abort support
 * - Detailed error tracking
 */

import { exponentialBackoff, type ExponentialBackoffOptions } from './exponentialBackoff';

/**
 * Creates a portable abort error that works in both browser and Node.js environments.
 * Falls back to a standard Error with 'AbortError' name when DOMException is unavailable.
 */
function createAbortError(message: string = 'Retry aborted'): Error {
  // Check if DOMException is available (browser or Node 17+)
  if (typeof DOMException !== 'undefined') {
    return new DOMException(message, 'AbortError');
  }
  // Fallback for older Node.js environments
  const error = new Error(message);
  error.name = 'AbortError';
  return error;
}

/**
 * Options for retry with backoff
 */
export interface RetryWithBackoffOptions extends ExponentialBackoffOptions {
  /**
   * Maximum number of attempts (default: 3).
   * Must be at least 1. Values less than 1 will be clamped to 1.
   */
  maxAttempts?: number;
  /** Custom function to determine if error is retryable (default: all errors) */
  shouldRetry?: (error: unknown, attempt: number) => boolean;
  /** Callback called before each retry attempt */
  onRetry?: (error: unknown, attempt: number, delay: number) => void;
  /** AbortSignal to cancel retries */
  signal?: AbortSignal;
}

/**
 * Result of retry operation
 */
export interface RetryResult<T> {
  /** Whether the operation succeeded */
  success: boolean;
  /** The result value if successful */
  data?: T;
  /** The last error if failed */
  error?: unknown;
  /**
   * Total number of attempts actually made.
   * For success: the attempt number that succeeded (1-indexed).
   * For failure: the number of attempts before giving up or being aborted.
   */
  attempts: number;
  /** Total time spent in milliseconds */
  totalTime: number;
  /**
   * Whether the operation was aborted via AbortSignal.
   * When true, the error will be an AbortError.
   */
  aborted?: boolean;
}

/**
 * Retry a promise-returning function with exponential backoff
 *
 * @param fn - Async function to retry
 * @param options - Retry configuration options
 * @returns Promise resolving to retry result (never rejects)
 *
 * @remarks
 * - The function always returns a structured `RetryResult`, even on abort.
 * - When aborted, `result.aborted` is `true` and `result.error` is an `AbortError`.
 * - The `attempts` field reflects actual attempts made, not the configured maximum.
 * - `maxAttempts` is clamped to at least 1 to prevent misconfiguration.
 *
 * @example
 * ```tsx
 * // Basic usage
 * const result = await retryWithBackoff(
 *   () => fetch('/api/data').then(r => r.json())
 * );
 *
 * if (result.success) {
 *   console.log('Data:', result.data);
 * } else {
 *   console.error('Failed after', result.attempts, 'attempts');
 * }
 *
 * // With custom options
 * const result = await retryWithBackoff(
 *   () => unstableApiCall(),
 *   {
 *     maxAttempts: 5,
 *     baseDelay: 500,
 *     shouldRetry: (error) => error instanceof NetworkError,
 *     onRetry: (error, attempt, delay) => {
 *       console.log(`Retry ${attempt} in ${delay}ms...`);
 *     }
 *   }
 * );
 *
 * // With abort support
 * const controller = new AbortController();
 * const result = await retryWithBackoff(
 *   () => longRunningOperation(),
 *   { signal: controller.signal }
 * );
 *
 * // Cancel after 5 seconds
 * setTimeout(() => controller.abort(), 5000);
 *
 * // Check if aborted
 * if (result.aborted) {
 *   console.log('Operation was cancelled');
 * }
 *
 * // Component usage with cleanup
 * useEffect(() => {
 *   const controller = new AbortController();
 *
 *   retryWithBackoff(
 *     () => fetchData(),
 *     { signal: controller.signal }
 *   ).then(result => {
 *     if (result.success) setData(result.data);
 *   });
 *
 *   return () => controller.abort();
 * }, []);
 * ```
 */
export async function retryWithBackoff<T>(
  fn: () => Promise<T>,
  options: RetryWithBackoffOptions = {}
): Promise<RetryResult<T>> {
  const {
    maxAttempts: rawMaxAttempts = 3,
    shouldRetry = () => true,
    onRetry,
    signal,
    ...backoffOptions
  } = options;

  // Clamp maxAttempts to at least 1 to prevent misconfiguration
  const maxAttempts = Math.max(1, rawMaxAttempts);

  const startTime = Date.now();
  let lastError: unknown;
  let attemptsMade = 0;

  for (let attempt = 0; attempt < maxAttempts; attempt++) {
    // Check for abort before attempt
    if (signal?.aborted) {
      return {
        success: false,
        error: createAbortError(),
        attempts: attemptsMade,
        totalTime: Date.now() - startTime,
        aborted: true,
      };
    }

    attemptsMade++;

    try {
      const data = await fn();
      return {
        success: true,
        data,
        attempts: attemptsMade,
        totalTime: Date.now() - startTime,
      };
    } catch (error) {
      lastError = error;

      // Check if we should retry
      const isLastAttempt = attempt >= maxAttempts - 1;
      if (isLastAttempt || !shouldRetry(error, attempt)) {
        break;
      }

      // Calculate delay and wait
      const delay = exponentialBackoff(attempt, backoffOptions);

      // Notify about retry
      onRetry?.(error, attempt + 1, delay);

      // Wait with abort support - returns structured result on abort instead of rejecting
      const aborted = await waitWithAbort(delay, signal);
      if (aborted) {
        return {
          success: false,
          error: createAbortError(),
          attempts: attemptsMade,
          totalTime: Date.now() - startTime,
          aborted: true,
        };
      }
    }
  }

  return {
    success: false,
    error: lastError,
    attempts: attemptsMade,
    totalTime: Date.now() - startTime,
  };
}

/**
 * Wait for a specified delay with abort support.
 * Returns true if aborted, false if completed normally.
 */
async function waitWithAbort(delayMs: number, signal?: AbortSignal): Promise<boolean> {
  return new Promise<boolean>((resolve) => {
    // If already aborted, resolve immediately
    if (signal?.aborted) {
      resolve(true);
      return;
    }

    const timeoutId = setTimeout(() => {
      if (signal) {
        signal.removeEventListener('abort', abortHandler);
      }
      resolve(false);
    }, delayMs);

    const abortHandler = (): void => {
      clearTimeout(timeoutId);
      resolve(true);
    };

    if (signal) {
      signal.addEventListener('abort', abortHandler, { once: true });
    }
  });
}

/**
 * @file withTimeout - Add timeout to promise
 * @module @dsai-io/react/utils/async
 *
 * Enterprise-grade timeout wrapper with:
 * - Configurable timeout duration
 * - Custom error message
 * - AbortController integration
 * - Cleanup on timeout
 */

/**
 * Options for timeout wrapper
 */
export interface WithTimeoutOptions {
  /** Custom error message for timeout */
  message?: string;
  /** AbortController to signal cancellation to the wrapped promise */
  controller?: AbortController;
}

/**
 * Error thrown when a promise times out
 */
export class TimeoutError extends Error {
  override readonly name = 'TimeoutError';
  readonly timeout: number;

  constructor(message: string, timeout: number) {
    super(message);
    this.timeout = timeout;
    // Maintains proper prototype chain for instanceof checks
    Object.setPrototypeOf(this, TimeoutError.prototype);
  }
}

/**
 * Wrap a promise with a timeout
 *
 * If the promise doesn't resolve within the specified time,
 * it rejects with a TimeoutError.
 *
 * @param promise - Promise to wrap
 * @param timeoutMs - Timeout in milliseconds
 * @param options - Timeout options
 * @returns Promise that rejects if timeout is exceeded
 *
 * @example
 * ```tsx
 * // Basic usage
 * try {
 *   const data = await withTimeout(
 *     fetch('/api/data'),
 *     5000
 *   );
 * } catch (error) {
 *   if (error instanceof TimeoutError) {
 *     console.log('Request timed out after', error.timeout, 'ms');
 *   }
 * }
 *
 * // With custom message
 * const result = await withTimeout(
 *   slowOperation(),
 *   10000,
 *   { message: 'Operation took too long' }
 * );
 *
 * // With AbortController for cleanup
 * const controller = new AbortController();
 * try {
 *   const data = await withTimeout(
 *     fetch('/api/data', { signal: controller.signal }),
 *     5000,
 *     { controller }
 *   );
 * } catch (error) {
 *   // Controller is automatically aborted on timeout
 *   console.log('Aborted:', controller.signal.aborted);
 * }
 *
 * // In React component
 * useEffect(() => {
 *   const controller = new AbortController();
 *
 *   withTimeout(
 *     fetchData({ signal: controller.signal }),
 *     5000,
 *     { controller }
 *   )
 *     .then(setData)
 *     .catch(error => {
 *       if (error.name !== 'AbortError') {
 *         setError(error);
 *       }
 *     });
 *
 *   return () => controller.abort();
 * }, []);
 * ```
 */
export async function withTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  options: WithTimeoutOptions = {}
): Promise<T> {
  const { message, controller } = options;

  if (timeoutMs <= 0) {
    console.warn('[withTimeout] Timeout must be > 0, using 1000ms');
    timeoutMs = 1000;
  }

  return new Promise<T>((resolve, reject) => {
    let settled = false;

    const timeoutId = setTimeout(() => {
      if (!settled) {
        settled = true;

        // Abort the controller if provided
        controller?.abort();

        const errorMessage = message ?? `Operation timed out after ${timeoutMs}ms`;
        reject(new TimeoutError(errorMessage, timeoutMs));
      }
    }, timeoutMs);

    promise
      .then((value) => {
        if (!settled) {
          settled = true;
          clearTimeout(timeoutId);
          resolve(value);
        }
      })
      .catch((error) => {
        if (!settled) {
          settled = true;
          clearTimeout(timeoutId);
          reject(error);
        }
      });
  });
}
